mapper.select:
select o.id , o.order_no as orderNo,o.merchant_id as merchantId,m.shop_name as merchantName, o.pay_amount as payAmount,o.status,o.create_time as createTime,o.source, o.receiver_name, o.receiver_phone, o.receiver_address from `order` o left join merchant_profile m on o.merchant_id = m.user_id
and o.user_id = #{userId}
and order_no like concat('%', #{dto.keyword}, '%')
and status = #{dto.status}
and o.source = #{dto.source}
and deleted = 0 ORDER BY CASE WHEN o.status = 0 THEN 0 ELSE 1 END, o.create_time DESC

select o.id,o.order_no as orderNo,o.pay_amount as payAmount,o.status,o.create_time as createTime, u.nickname as buyerName,o.source from `order` o left join user_profile u on o.user_id = u.user_id left join merchant_profile mp on o.merchant_id = mp.id
and order_no like concat('%', #{dto.orderNo}, '%')
and u.nickname like concat('%', #{dto.buyerName}, '%')
and status = #{dto.status}
and o.source = #{dto.source}
and deleted = 0 and o.merchant_id = #{merchantId}
order by o.create_time desc

select date_format(create_time, '%m-%d') as date, ifnull(sum(pay_amount), 0) as amount
from `order` where status in (1,2,3) and create_time >= date_sub(curdate(), interval 7 day)
group by date_format(create_time, '%m-%d') order by date_format(create_time, '%m-%d')

select date_format(create_time, '%m-%d') as date, ifnull(sum(pay_amount), 0) as amount
from `order` where status in (1,2,3) and create_time >= date_sub(curdate(), interval 7 day)
and merchant_id = #{merchantId}
group by date_format(create_time, '%m-%d') order by date_format(create_time, '%m-%d')
